int factorial(int n)
{
    int totalValueSoFar = 1;
    int loopCounter = 1;
    int checkFlag = 0;
    if(n == 0)
    {
        totalValueSoFar = 1;
        checkFlag = 1;
    }
    else
    {
        while(loopCounter <= n)
        {
            totalValueSoFar = totalValueSoFar * loopCounter;
            loopCounter = loopCounter + 1;
        }
        checkFlag = 1;
    }
    if(checkFlag == 1)
    {
        return totalValueSoFar;
    }
    else
    {
        return totalValueSoFar;
    }
    return totalValueSoFar;
}
